// Package harness is harnaas's roster of the harnesses it recognizes.
//
// The roster is data only: an id, a display name, whether the harness has an
// unambiguous per-user location, and the observable evidence that a project is
// already using it. It maps nothing to a destination and it writes nothing. The
// adapters that turn an asset into a file on disk arrive with `harnaas install`
// and attach themselves to these ids.
//
// That seam is deliberate. Three things in this change need to know a harness
// exists — manifest validation must reject an unrecognized target, scope
// validation must know whether `user` scope has anywhere to go, and `init` must
// detect which harnesses a project already uses — while none of them needs to
// know where a skill lands. Deferring the roster until the adapters exist would
// force the manifest to accept any string as a harness name and reject it two
// phases later, at a point where the error can no longer name the line that
// caused it.
//
// A harness in the manifest's `harnesses` list is a guarantee, not an
// observation: it means "we guarantee the declared assets work for this
// harness". Because skills and instructions land in shared locations that
// several harnesses read, a harness absent from the list will still see assets
// installed for one that is present. That is why an unrecognized name is an
// error — it is a guarantee harnaas cannot make — and why an asset being
// visible to a harness nobody listed is not.
package harness

// ID is a harness's canonical identifier: the exact string a manifest writes in
// its `harnesses` list or an asset's `targets`, and the key an adapter will
// later register itself under.
//
// It is a named type rather than a bare string so a function taking a harness
// cannot silently be handed an asset id, a source key or a display name.
type ID string

// ClaudeCode is the only harness this change recognizes. More arrive with the
// adapters; the roster is where they are declared, one entry each.
const ClaudeCode ID = "claude-code"

// Default is the harness `harnaas init` scaffolds a manifest with when it
// detects none in the project. A default is what keeps init from ever writing
// an empty `harnesses` list, which would be a manifest that declares assets and
// guarantees them for nothing.
const Default = ClaudeCode

// Harness describes one recognized harness. Every field is data a caller reads;
// there is no behaviour here, and adding some is how the roster and the
// adapters start to disagree.
type Harness struct {
	// ID is the canonical identifier, and the only spelling a manifest may
	// use. Display names are never accepted as input.
	ID ID

	// DisplayName is what harnaas prints when it names the harness to a user.
	// It is never parsed, and never compared against manifest input.
	DisplayName string

	// PerUserLocation records whether the harness reads assets from an
	// unambiguous location in the user's home as well as from the project.
	//
	// This is what decides whether an asset may declare `user` scope for this
	// target. It is a property of the harness, not a preference: where a
	// harness has no single per-user root, or several that disagree, harnaas
	// has no correct answer and says so rather than guessing one.
	PerUserLocation bool

	// ProjectEvidence lists the project-root-relative paths whose presence
	// means the project is already using this harness. Any one of them is
	// enough.
	//
	// Evidence is observable state in the repository, never configuration the
	// user has not written yet: `init` runs before harnaas knows anything about
	// the project, so the only thing it can read is what the harness itself has
	// already left behind. The entries are paths rather than a predicate
	// because the roster stays data — `init` does the stat calls.
	ProjectEvidence []string
}

// roster is every recognized harness, ordered by ID.
//
// The order is the one callers see, so it has to be a property of the data
// rather than of how the literal happens to be written — a manifest error
// listing recognized harnesses must read identically on every run and every
// machine. TestRosterIsOrderedByID pins it, so an entry added in the wrong
// place fails a test instead of quietly reordering somebody's error message.
var roster = []Harness{
	{
		ID:              ClaudeCode,
		DisplayName:     "Claude Code",
		PerUserLocation: true,
		ProjectEvidence: []string{".claude", "CLAUDE.md"},
	},
}
package harness_test

import (
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
)

func TestDefaultIsItselfRecognized(t *testing.T) {
	t.Parallel()

	// init falls back to Default when it detects nothing, and manifest
	// validation rejects a harness the roster does not recognize. A Default
	// outside the roster would make init scaffold a manifest that harnaas
	// itself refuses to load.
	assert.True(t, harness.Recognized(harness.Default),
		"the default harness %q is not in the roster", harness.Default)

	found, err := harness.Lookup(harness.Default)
	require.NoError(t, err)
	assert.Equal(t, harness.Default, found.ID)
}

func TestRosterIsOrderedByID(t *testing.T) {
	t.Parallel()

	ids := harness.IDs()
	require.NotEmpty(t, ids)
	assert.True(t, slices.IsSorted(ids),
		"the roster must be declared in id order so every list harnaas prints reads the same: %v", ids)
}

func TestIDOrderIsStableAcrossCalls(t *testing.T) {
	t.Parallel()

	// The roster is a slice rather than a map precisely so this holds. A map
	// would give a different order on every run, and the order is what an
	// "unknown harness" message and a scaffolded manifest are both built from.
	first := harness.IDs()
	for range 8 {
		assert.Equal(t, first, harness.IDs())
	}
}

func TestEveryEntryIsUsable(t *testing.T) {
	t.Parallel()

	seen := map[harness.ID]bool{}
	for _, h := range harness.All() {
		assert.NotEmpty(t, h.ID, "a roster entry has no id")
		assert.NotEmpty(t, h.DisplayName, "%s has no display name", h.ID)
		assert.NotEmpty(t, h.ProjectEvidence,
			"%s declares no project evidence, so init could never detect it", h.ID)

		assert.False(t, seen[h.ID], "%s is declared twice", h.ID)
		seen[h.ID] = true

		for _, evidence := range h.ProjectEvidence {
			assert.False(t, filepath.IsAbs(evidence),
				"%s: evidence %q must be relative to the project root", h.ID, evidence)
			assert.NotContains(t, evidence, "..",
				"%s: evidence %q reaches outside the project", h.ID, evidence)
		}
	}
}

func TestUnknownIDErrorNamesTheInputAndListsTheRecognizedOnes(t *testing.T) {
	t.Parallel()

	_, err := harness.Lookup("claud-code")

	var unknown *harness.UnknownError
	require.ErrorAs(t, err, &unknown)
	assert.Equal(t, harness.ID("claud-code"), unknown.ID)
	assert.Equal(t, harness.IDs(), unknown.Recognized)

	message := err.Error()
	assert.Contains(t, message, `"claud-code"`, "the message must quote the id as written")
	for _, id := range harness.IDs() {
		assert.Contains(t, message, string(id))
	}

	// Problem, blank line, then the fix — the shape every harnaas diagnostic has.
	problem, fix, split := strings.Cut(message, "\n\n")
	require.True(t, split, "the message must separate the problem from the fix with a blank line")
	assert.NotContains(t, problem, "\n")
	assert.NotEmpty(t, fix)
}

func TestUnknownIDErrorMessageIsIdenticalAcrossRuns(t *testing.T) {
	t.Parallel()

	_, first := harness.Lookup("nope")
	for range 8 {
		_, again := harness.Lookup("nope")
		assert.Equal(t, first.Error(), again.Error())
	}
}

package harness

import (
	"fmt"
	"slices"
	"strings"
)

// UnknownError reports a harness id the roster does not recognize.
//
// It is a type rather than a formatted string so manifest validation can
// recognise the condition — and attribute it to the asset entry or the
// `harnesses` list that produced it — without matching on message text.
type UnknownError struct {
	// ID is the unrecognized id exactly as it was written, so the message can
	// quote the manifest back to its author rather than paraphrase it.
	ID ID

	// Recognized is every id the roster does recognize, in the roster's order.
	// It is captured rather than looked up at render time so the error stays a
	// complete diagnostic wherever it is finally printed.
	Recognized []ID
}

// Error states the problem and the edit that fixes it, in that order, as every
// user-facing diagnostic does.
//
// Listing the recognized ids is most of the fix: the failure is almost always a
// misspelling or a harness harnaas does not support yet, and those two need
// different responses from the author.
func (e *UnknownError) Error() string {
	names := make([]string, 0, len(e.Recognized))
	for _, id := range e.Recognized {
		names = append(names, string(id))
	}

	return fmt.Sprintf(
		"unknown harness %q\n\n"+
			"Use a harness harnaas recognizes: %s.",
		e.ID, strings.Join(names, ", "),
	)
}

// IDs returns every recognized harness id in the roster's order.
//
// Callers get a fresh slice, because this list is rendered into user-facing
// errors and sorted into manifests; a caller that reorders it in place would
// change what every later message says.
func IDs() []ID {
	ids := make([]ID, 0, len(roster))
	for _, h := range roster {
		ids = append(ids, h.ID)
	}
	return ids
}

// All returns every recognized harness in the roster's order.
//
// The returned entries are copies down to their evidence slices, so the roster
// cannot be edited through a value a caller was handed.
func All() []Harness {
	all := make([]Harness, 0, len(roster))
	for _, h := range roster {
		all = append(all, clone(h))
	}
	return all
}

// Lookup returns the harness with the given id, or an *UnknownError naming the
// input and listing what harnaas does recognize.
func Lookup(id ID) (Harness, error) {
	for _, h := range roster {
		if h.ID == id {
			return clone(h), nil
		}
	}
	return Harness{}, &UnknownError{ID: id, Recognized: IDs()}
}

// Recognized reports whether id names a harness in the roster. It is the
// question to ask where the answer is a branch rather than a diagnostic; where
// it is a diagnostic, call Lookup and return its error, which already names the
// input and the alternatives.
func Recognized(id ID) bool {
	return slices.ContainsFunc(roster, func(h Harness) bool { return h.ID == id })
}

// HasPerUserLocation reports whether the harness reads assets from an
// unambiguous per-user location. This is the query manifest scope validation
// calls to decide whether an asset may declare `user` scope for this target.
//
// An unrecognized id is an error and never a false: "harnaas does not know this
// harness" and "this harness has no per-user location" call for different edits
// from the author, and collapsing them would report the second for a typo.
func HasPerUserLocation(id ID) (bool, error) {
	h, err := Lookup(id)
	if err != nil {
		return false, err
	}
	return h.PerUserLocation, nil
}

// clone copies a roster entry and its evidence slice, so a caller holding the
// result shares no backing array with the roster.
func clone(h Harness) Harness {
	h.ProjectEvidence = slices.Clone(h.ProjectEvidence)
	return h
}

